package com.healthcare.portal.entity;
import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="audit_logs",indexes={@Index(name="idx_audit_actor",columnList="actor_user_id"),@Index(name="idx_audit_created",columnList="created_at")})
public class AuditLog { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="actor_user_id") private User actor; @Column(nullable=false,length=80) private String action; @Column(length=80) private String entityType; private Long entityId; @Column(columnDefinition="TEXT") private String details; @Column(name="ip_address",length=64) private String ipAddress; @Column(name="created_at") private LocalDateTime createdAt; @PrePersist void c(){createdAt=LocalDateTime.now();} public AuditLog(){} public AuditLog(User a,String action,String type,Long id,String details){actor=a;this.action=action;entityType=type;entityId=id;this.details=details;} public Long getId(){return id;} public User getActor(){return actor;} public String getAction(){return action;} public String getEntityType(){return entityType;} public Long getEntityId(){return entityId;} public String getDetails(){return details;} public LocalDateTime getCreatedAt(){return createdAt;} }
